import { z } from 'zod';
import {
  ONBOARDING_COMPLEXITIES,
  ONBOARDING_LANGUAGE,
  ONBOARDING_LIMITS,
  ONBOARDING_NODE_KINDS,
  ONBOARDING_SECTION_IDS,
  ONBOARDING_STALE_REASONS,
} from '../constants/onboarding.js';

/**
 * Onboarding Tour — a five-part tour of one repo, generated by one LLM call over the
 * repo-intel index and stored per repo. Limits live in constants/onboarding (zod-free).
 * A section below its minimum is stored empty, so only the maximums are enforced here.
 */
export {
  ONBOARDING_COMPLEXITIES,
  ONBOARDING_LANGUAGE,
  ONBOARDING_LIMITS,
  ONBOARDING_NODE_KINDS,
  ONBOARDING_SECTION_IDS,
  ONBOARDING_STALE_REASONS,
};
export type { OnboardingSectionId } from '../constants/onboarding.js';

const L = ONBOARDING_LIMITS;

export const OnboardingNodeKind = z.enum(ONBOARDING_NODE_KINDS);
export type OnboardingNodeKind = z.infer<typeof OnboardingNodeKind>;

export const OnboardingComplexity = z.enum(ONBOARDING_COMPLEXITIES);
export type OnboardingComplexity = z.infer<typeof OnboardingComplexity>;

export const OnboardingStaleReason = z.enum(ONBOARDING_STALE_REASONS);
export type OnboardingStaleReason = z.infer<typeof OnboardingStaleReason>;

export const OnboardingNode = z.object({
  id: z.string().min(1).max(L.nodeIdMax),
  label: z.string().min(1).max(L.nodeLabelMax),
  kind: OnboardingNodeKind,
});
export type OnboardingNode = z.infer<typeof OnboardingNode>;

export const OnboardingEdge = z.object({
  from: z.string().min(1).max(L.nodeIdMax),
  to: z.string().min(1).max(L.nodeIdMax),
});
export type OnboardingEdge = z.infer<typeof OnboardingEdge>;

export const OnboardingArchitecture = z.object({
  summary: z.string().max(L.summaryMax),
  nodes: z.array(OnboardingNode).max(L.nodesMax),
  edges: z.array(OnboardingEdge).max(L.edgesMax),
});
export type OnboardingArchitecture = z.infer<typeof OnboardingArchitecture>;

export const OnboardingPathItem = z.object({
  path: z.string().min(1).max(L.pathMax),
  reason: z.string().max(L.reasonMax),
});
export type OnboardingPathItem = z.infer<typeof OnboardingPathItem>;

export const OnboardingRunStep = z.object({
  command: z.string().min(1).max(L.commandMax),
  comment: z.string().max(L.commentMax).optional(),
});
export type OnboardingRunStep = z.infer<typeof OnboardingRunStep>;

export const OnboardingFirstTask = z.object({
  title: z.string().min(1).max(L.taskTitleMax),
  /** An indexed file, or a folder with indexed files under it. */
  path: z.string().min(1).max(L.pathMax),
  complexity: OnboardingComplexity,
});
export type OnboardingFirstTask = z.infer<typeof OnboardingFirstTask>;

export const OnboardingTour = z.object({
  repo_id: z.string(),
  generated_at: z.string(),
  indexed_sha: z.string(),
  files_indexed: z.number().int(),
  provider: z.string(),
  model: z.string(),
  tokens_in: z.number().int(),
  tokens_out: z.number().int(),
  /** null when the model is unpriced. */
  cost_usd: z.number().nullable(),
  prompt_version: z.number().int(),
  language: z.literal(ONBOARDING_LANGUAGE),
  architecture: OnboardingArchitecture,
  critical_paths: z.array(OnboardingPathItem).max(L.criticalPathsMax),
  run_steps: z.array(OnboardingRunStep).max(L.runStepsMax),
  reading_path: z.array(OnboardingPathItem).max(L.readingPathMax),
  first_tasks: z.array(OnboardingFirstTask).max(L.firstTasksMax),
});
export type OnboardingTour = z.infer<typeof OnboardingTour>;

/** GET /repos/:id/onboarding → none, or the stored tour plus its derived stale flag. */
export const OnboardingTourNone = z.object({ status: z.literal('none') });
export type OnboardingTourNone = z.infer<typeof OnboardingTourNone>;

export const OnboardingTourReady = z.object({
  status: z.literal('ready'),
  stale: z.boolean(),
  stale_reason: OnboardingStaleReason.optional(),
  tour: OnboardingTour,
});
export type OnboardingTourReady = z.infer<typeof OnboardingTourReady>;

export const OnboardingTourState = z.discriminatedUnion('status', [
  OnboardingTourNone,
  OnboardingTourReady,
]);
export type OnboardingTourState = z.infer<typeof OnboardingTourState>;
